#!/bin/sh
# Name: KindleChess
# Author: BarPos
# Icon: data:image/png;base64,
# DontUseFBInk

#Based On ILLUSION, My Scriptlet For Creating Easy Mesquite Applications.
#Credit To HackerDude For OG Source (Modified A Bit For Stuffs)

SOURCE_DIR="/mnt/us/documents/KindleChess"
TARGET_DIR="/var/local/mesquite/KindleChess"
DB="/var/local/appreg.db"
APP_ID="net.barpos.kindlechess"
LOG="$SOURCE_DIR/startup.log"

log() {
    echo "$(date '+%Y-%m-%d %H:%M:%S') $1" | tee -a "$LOG"
}

: > "$LOG"
log "KindleChess.sh start pid $$"
log "source $SOURCE_DIR"
log "target $TARGET_DIR"

#Copy To VAR/LOCAL/MESQUITE
if [ -d "$SOURCE_DIR" ]; then
    log "source directory exists"
    if [ -d "$TARGET_DIR" ]; then
        log "removing old target"
        rm -rf "$TARGET_DIR"
        log "remove exit $?"
    fi
    cp -r "$SOURCE_DIR" "$TARGET_DIR"
    log "copy exit $?"
    log "target files:"
    find "$TARGET_DIR" -type f | tee -a "$LOG"
else
    log "source directory missing, exit 1"
    exit 1
fi

#Redeclare To APPREG.DB
log "registering $APP_ID"
sqlite3 "$DB" <<EOF
INSERT OR IGNORE INTO interfaces(interface) VALUES('application');

INSERT OR IGNORE INTO handlerIds(handlerId) VALUES('$APP_ID');

INSERT OR REPLACE INTO properties(handlerId,name,value) 
  VALUES('$APP_ID','lipcId','$APP_ID');
INSERT OR REPLACE INTO properties(handlerId,name,value) 
  VALUES('$APP_ID','command','/usr/bin/mesquite -l $APP_ID -c file://$TARGET_DIR/');
INSERT OR REPLACE INTO properties(handlerId,name,value) 
  VALUES('$APP_ID','supportedOrientation','U');
EOF
log "sqlite exit $?"

log "registered $APP_ID"

# Starting the app ends this script, so the stop/wait/start has to be its own session.
cat > /var/tmp/KindleChess-statusbar.sh <<EOF
#!/bin/sh
APP_ID="$APP_ID"
LOG="$LOG"
log() {
    echo "\$(date '+%Y-%m-%d %H:%M:%S') \$1" >> "\$LOG"
}
trap '' HUP
sleep 5
log "running /sbin/stop statusbar"
/sbin/stop statusbar >> "\$LOG" 2>&1
log "stop statusbar exit \$?"
log "Starting wait loop"
while [ "\$(lipc-get-prop com.lab126.appmgrd activeApp)" = "\$APP_ID" ]; do
    log "waiting for lipc-wait-event"
    lipc-wait-event com.lab126.appmgrd >> "\$LOG" 2>&1
    log "lipc-wait-event exit \$?"
    sleep 2
    log "hit lipc-wait-event"
done
sleep 1
log "running /sbin/start statusbar"
/sbin/start statusbar >> "\$LOG" 2>&1
log "start statusbar exit \$?"
log "KindleChess.sh done, log is \$LOG"
EOF

if command -v setsid >/dev/null 2>&1; then
    SETSID=setsid
elif [ -x /usr/bin/setsid ]; then
    SETSID=/usr/bin/setsid
else
    SETSID=
fi

if [ -n "$SETSID" ]; then
    $SETSID /bin/sh /var/tmp/KindleChess-statusbar.sh </dev/null >/dev/null 2>&1 &
else
    /bin/sh /var/tmp/KindleChess-statusbar.sh </dev/null >/dev/null 2>&1 &
fi
log "statusbar watcher pid $!"

# Launch through the app manager. Running mesquite directly leaves a white screen.
log "starting app://$APP_ID"
lipc-set-prop com.lab126.appmgrd start app://$APP_ID >> "$LOG" 2>&1
log "lipc exit $?"
